import { chromium } from 'playwright';

const browser = await chromium.launch();

async function loadStory(id, width, height = 700) {
  const page = await browser.newPage({ viewport: { width, height } });
  await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(800);
  return page;
}

// --- 1. discountLabel/message DOM order relative to stepper ---
console.log('=== 1. DOM order: stepper -> discountLabel/message ===');
for (const id of ['commerce-productitem--with-discount-label', 'commerce-productitem--with-warning-message', 'commerce-productitem--with-error-message']) {
  const page = await loadStory(id, 1440);
  const order = await page.evaluate(() => {
    const stepper = document.querySelector('[aria-label*="Increase" i]')?.closest('div[class*="css-"]');
    const discount = document.querySelector('[data-testid="zimm-discount-label"]');
    const message = document.querySelector('[data-testid="zimm-inline-message"]');
    const nodes = [];
    if (stepper) nodes.push(['stepper', stepper]);
    if (discount) nodes.push(['discountLabel', discount]);
    if (message) nodes.push(['message', message]);
    // sort by DOCUMENT_POSITION
    nodes.sort((a, b) => {
      const pos = a[1].compareDocumentPosition(b[1]);
      return pos & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
    });
    return nodes.map(n => n[0]);
  });
  console.log(id, '-> order:', JSON.stringify(order));
  await page.close();
}

// --- 2. Image alignment within row ---
console.log('=== 2. Image row alignment ===');
for (const [label, width] of [['mobile', 400], ['desktop', 1440]]) {
  const page = await loadStory('commerce-productitem--default', width);
  const info = await page.evaluate(() => {
    const img = document.querySelector('img');
    const heading = document.querySelector('h2');
    if (!img || !heading) return { found: false };
    const imgRect = img.getBoundingClientRect();
    const headingRect = heading.getBoundingClientRect();
    // find the row container (common ancestor) alignItems
    let row = img.parentElement;
    while (row && !row.contains(heading)) row = row.parentElement;
    const rowAlign = row ? getComputedStyle(row).alignItems : 'not found';
    return {
      found: true,
      imgTop: Math.round(imgRect.top), imgHeight: Math.round(imgRect.height), imgCenterY: Math.round(imgRect.top + imgRect.height / 2),
      headingTop: Math.round(headingRect.top),
      rowAlignItems: rowAlign,
    };
  });
  console.log(label, JSON.stringify(info));
  await page.close();
}

// --- 3. stepper-to-primaryAction row ---
console.log('=== 3. Stepper / primaryAction row ===');
for (const [label, width] of [['mobile', 400], ['desktop', 1440]]) {
  const page = await loadStory('commerce-productitem--default', width);
  const info = await page.evaluate(() => {
    const stepperBtn = document.querySelector('[aria-label*="Increase" i]');
    const removeBtn = Array.from(document.querySelectorAll('button')).find(b => /remove/i.test(b.textContent || ''));
    if (!stepperBtn || !removeBtn) return { found: false, hasStepper: !!stepperBtn, hasRemove: !!removeBtn };
    const s = stepperBtn.getBoundingClientRect();
    const r = removeBtn.getBoundingClientRect();
    return {
      found: true,
      sameRowY: Math.abs(s.top - r.top) < 20,
      stepperX: Math.round(s.left), removeX: Math.round(r.left),
      stepperY: Math.round(s.top), removeY: Math.round(r.top),
    };
  });
  console.log(label, JSON.stringify(info));
  await page.close();
}

// --- 4. ZimmCartDrawer internal vertical order ---
console.log('=== 4. ZimmCartDrawer composition order ===');
for (const [label, width] of [['narrow', 500], ['wide', 1600]]) {
  const page = await loadStory('commerce-zimmcartdrawer--default', width, 900);
  const info = await page.evaluate(() => {
    const header = Array.from(document.querySelectorAll('*')).find(el => /BAG/.test(el.textContent || '') && el.children.length === 0);
    const body = document.querySelector('p'); // "Line items" placeholder text from the story
    if (!header) return { found: false };
    const h = header.getBoundingClientRect();
    const b = body ? body.getBoundingClientRect() : null;
    return {
      found: true,
      headerY: Math.round(h.top),
      bodyY: b ? Math.round(b.top) : 'not found',
      headerBeforeBody: b ? h.top < b.top : 'n/a',
    };
  });
  console.log(label, JSON.stringify(info));
  await page.close();
}

await browser.close();

