  await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmcartdrawer--default&viewMode=story', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
    const all = Array.from(document.querySelectorAll('*'));
    const header = all.find(el => /BAG/.test(el.textContent || '') && el.children.length === 0);
    const body = all.find(el => /ProductItem list is wired/.test(el.textContent || '') && el.children.length === 0);
    const footer = all.find(el => /button group lands here/.test(el.textContent || '') && el.children.length === 0);
    if (!header || !body || !footer) return { found: false, hasHeader: !!header, hasBody: !!body, hasFooter: !!footer };
    const h = header.getBoundingClientRect();
    const b = body.getBoundingClientRect();
    const f = footer.getBoundingClientRect();
    return {
      found: true,
      headerY: Math.round(h.top), bodyY: Math.round(b.top), footerY: Math.round(f.top),
      orderCorrect: h.top < b.top && b.top < f.top,
    };
  });
  console.log(label, JSON.stringify(info));
  await page.close();
}
await browser.close();
